# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
#
# Chebyshev polynomial of the first kind, T_n(x), elementwise.
#
# Matches ATen semantics: the degree is truncated toward zero, n < 0 yields 0,
# and the value is produced by the three-term recurrence
#     T_0 = 1, T_1 = x, T_k = 2 * x * T_{k-1} - T_{k-2}
# evaluated in the input dtype (only float32/float64 are supported).
#
# Target notes (Enflame GCU300):
#   * int64 is stored as ONE dense int32 word per element and 64-bit data types
#     are rejected by the kernel compiler ("64-bit data type not supported on
#     GCU300"), so an int64 degree tensor is fed through a zero-copy int32 word
#     view indexed with the element index (NOT a stride-2 view: that reads the
#     wrong word).
#   * the compile-time geometry search (17 configs) cost minutes per run on this
#     backend, so the launch geometry is chosen on the host instead: a persistent
#     grid with ~16 tiles per program for big tensors, num_warps=1.
import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_FLOAT_DTYPES = (torch.float32, torch.float64)
_BLOCK = 1024
_MAX_DIMS = 8
_MAX_GRID = 65535

# Geometry for the grid-strided scalar-degree kernels.  Program count costs
# ~0.46us each on this backend, so big launches use a persistent grid (~16
# tiles per program, at least 64 programs) with fat tiles.
_BLOCK_BIG = 16384  # measured best at every size >= 96K (micro-tune, nw=1)
_TARGET_ITERS = 16
_MIN_PROGRAMS = 64
_WARPS_BIG = 1
# Kernels with a runtime per-lane degree keep the original geometry: they do
# not compile with the fat tile / num_warps=1 on this target.
_NUM_WARPS = 4

# Totals at or below this limit are host-bound on this target (the device kernel
# is only a few microseconds), so they use a fixed, small geometry.
_SMALL_TOTAL = 65536
_SMALL_BLOCK = 1024
_SMALL_WARPS = 4


def _pick(total):
    """(BLOCK, grid.x, num_warps) for a grid-strided launch over `total`.

    Fat tiles plus a persistent grid: on this backend each extra program costs
    ~0.5us of dispatch, which dominated the small/mid sizes entirely
    (1024-wide tiles: 508us vs 65us for 1M elements).
    """
    block = _BLOCK_BIG
    nblocks = triton.cdiv(total, block)
    grid = min(
        nblocks, max(_MIN_PROGRAMS, triton.cdiv(nblocks, _TARGET_ITERS)), _MAX_GRID
    )
    return block, grid, _WARPS_BIG


@triton.jit
def _cheb_t_recurrence(x, DEGREE: tl.constexpr, BLOCK: tl.constexpr):
    prev = tl.full([BLOCK], 1.0, x.dtype)
    curr = x
    for _ in range(1, DEGREE):
        nxt = 2.0 * x * curr - prev
        prev = curr
        curr = nxt
    return curr


@triton.jit
def _cheb_t_uniform_degree(x, nv, BLOCK: tl.constexpr):
    """Recurrence with a per-program (uniform) runtime degree.

    The small degrees keep exactly the loop's association order
    (T_k = 2*x*T_{k-1} - T_{k-2}), so the results are unchanged; the explicit
    ladder only removes the dynamic loop bookkeeping for the common degrees.
    """
    if nv < 0:
        res = tl.full([BLOCK], 0.0, x.dtype)
    elif nv == 0:
        res = tl.full([BLOCK], 1.0, x.dtype)
    elif nv == 1:
        res = x
    elif nv == 2:
        res = 2.0 * x * x - 1.0
    elif nv == 3:
        t2 = 2.0 * x * x - 1.0
        res = 2.0 * x * t2 - x
    elif nv == 4:
        t2 = 2.0 * x * x - 1.0
        t3 = 2.0 * x * t2 - x
        res = 2.0 * x * t3 - t2
    elif nv == 5:
        t2 = 2.0 * x * x - 1.0
        t3 = 2.0 * x * t2 - x
        t4 = 2.0 * x * t3 - t2
        res = 2.0 * x * t4 - t3
    else:
        prev = tl.full([BLOCK], 1.0, x.dtype)
        curr = x
        for _ in range(1, nv):
            nxt = 2.0 * x * curr - prev
            prev = curr
            curr = nxt
        res = curr
    return res


@triton.jit
def _cheb_t_small_kernel(
    x_ptr, out_ptr, total, DEGREE: tl.constexpr, BLOCK: tl.constexpr
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < total
    if DEGREE < 0:
        res = tl.full([BLOCK], 0.0, out_ptr.dtype.element_ty)
    elif DEGREE == 0:
        res = tl.full([BLOCK], 1.0, out_ptr.dtype.element_ty)
    else:
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        res = _cheb_t_recurrence(x, DEGREE, BLOCK)
    tl.store(out_ptr + offs, res, mask=mask)


@triton.jit
def _cheb_t_small_n_kernel(x_ptr, n_ptr, out_ptr, total, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < total
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    nv = tl.load(n_ptr).to(tl.int32)
    res = _cheb_t_uniform_degree(x, nv, BLOCK)
    tl.store(out_ptr + offs, res, mask=mask)


@triton.jit
def _cheb_t_scalar_kernel(
    x_ptr, out_ptr, total, DEGREE: tl.constexpr, BLOCK: tl.constexpr
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    base = pid * BLOCK
    iters = (total - base + step - 1) // step
    for it in range(0, iters):
        offs = base + it * step + tl.arange(0, BLOCK)
        mask = offs < total
        if DEGREE == 0:
            # T_0 is the constant 1: no need to read x at all.
            res = tl.full([BLOCK], 1.0, out_ptr.dtype.element_ty)
        else:
            x = tl.load(x_ptr + offs, mask=mask, other=0.0)
            # The degree ladder emits the same three-term recurrence but
            # schedules ~1.6x faster than the carried prev/curr loop here.
            res = _cheb_t_uniform_degree(x, DEGREE, BLOCK)
        tl.store(out_ptr + offs, res, mask=mask)


@triton.jit
def _cheb_t_scalar_n_kernel(x_ptr, n_ptr, out_ptr, total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    base = pid * BLOCK
    iters = (total - base + step - 1) // step
    nv = tl.load(n_ptr).to(tl.int32)
    for it in range(0, iters):
        offs = base + it * step + tl.arange(0, BLOCK)
        mask = offs < total
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        res = _cheb_t_uniform_degree(x, nv, BLOCK)
        tl.store(out_ptr + offs, res, mask=mask)


@triton.jit
def _cheb_t_tensor_kernel(x_ptr, n_ptr, out_ptr, total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    base = pid * BLOCK
    iters = (total - base + step - 1) // step
    for it in range(0, iters):
        offs = base + it * step + tl.arange(0, BLOCK)
        mask = offs < total
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        # n_ptr is a dense int32 word view: one word per degree element.
        nv = tl.load(n_ptr + offs, mask=mask, other=0).to(tl.int32)
        top = tl.max(nv, axis=0)
        prev = tl.full([BLOCK], 1.0, x.dtype)
        curr = x
        for k in range(2, top + 1):
            nxt = 2.0 * x * curr - prev
            active = k <= nv
            prev = tl.where(active, curr, prev)
            curr = tl.where(active, nxt, curr)
        curr = tl.where(nv == 0, 1.0, curr)
        curr = tl.where(nv < 0, 0.0, curr)
        tl.store(out_ptr + offs, curr, mask=mask)


@triton.jit
def _cheb_t_strided_kernel(
    x_ptr,
    n_ptr,
    out_ptr,
    total,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xs6,
    xs7,
    ns0,
    ns1,
    ns2,
    ns3,
    ns4,
    ns5,
    ns6,
    ns7,
    DEGREE: tl.constexpr,
    HAS_N: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    base = pid * BLOCK
    iters = (total - base + step - 1) // step
    for it in range(0, iters):
        offs = base + it * step + tl.arange(0, BLOCK)
        mask = offs < total
        rem = offs
        xo = tl.zeros([BLOCK], tl.int32)
        no = tl.zeros([BLOCK], tl.int32)
        q = rem % d7
        rem = rem // d7
        xo += q * xs7
        no += q * ns7
        q = rem % d6
        rem = rem // d6
        xo += q * xs6
        no += q * ns6
        q = rem % d5
        rem = rem // d5
        xo += q * xs5
        no += q * ns5
        q = rem % d4
        rem = rem // d4
        xo += q * xs4
        no += q * ns4
        q = rem % d3
        rem = rem // d3
        xo += q * xs3
        no += q * ns3
        q = rem % d2
        rem = rem // d2
        xo += q * xs2
        no += q * ns2
        q = rem % d1
        rem = rem // d1
        xo += q * xs1
        no += q * ns1
        q = rem % d0
        xo += q * xs0
        no += q * ns0

        if HAS_N:
            x = tl.load(x_ptr + xo, mask=mask, other=0.0)
            nv = tl.load(n_ptr + no, mask=mask, other=0).to(tl.int32)
            top = tl.max(nv, axis=0)
            prev = tl.full([BLOCK], 1.0, x.dtype)
            curr = x
            for k in range(2, top + 1):
                nxt = 2.0 * x * curr - prev
                active = k <= nv
                prev = tl.where(active, curr, prev)
                curr = tl.where(active, nxt, curr)
            curr = tl.where(nv == 0, 1.0, curr)
            curr = tl.where(nv < 0, 0.0, curr)
            res = curr
        elif DEGREE < 0:
            res = tl.full([BLOCK], 0.0, out_ptr.dtype.element_ty)
        elif DEGREE == 0:
            res = tl.full([BLOCK], 1.0, out_ptr.dtype.element_ty)
        else:
            x = tl.load(x_ptr + xo, mask=mask, other=0.0)
            prev = tl.full([BLOCK], 1.0, x.dtype)
            curr = x
            for _ in range(1, DEGREE):
                nxt = 2.0 * x * curr - prev
                prev = curr
                curr = nxt
            res = curr
        tl.store(out_ptr + offs, res, mask=mask)


def _grid(total, block):
    return (min(triton.cdiv(total, block), _MAX_GRID),)


def _pad_dims(t, scale=1):
    """Right-align shape/stride onto _MAX_DIMS slots (pad with 1 / 0)."""
    dims = [1] * _MAX_DIMS
    strides = [0] * _MAX_DIMS
    shape = t.shape
    st = t.stride()
    nd = len(shape)
    if nd > _MAX_DIMS:
        raise NotImplementedError(
            f"special_chebyshev_polynomial_t supports at most {_MAX_DIMS} dims"
        )
    for i in range(nd):
        dims[_MAX_DIMS - nd + i] = shape[i]
        strides[_MAX_DIMS - nd + i] = st[i] * scale
    return dims, strides


def _word_view(t, numel=None):
    """Dense zero-copy int32 view of an int64 degree tensor.

    On this backend int64 is stored as one dense int32 word per element, so the
    degree of element i is word i (a stride-2 read would take the wrong word).
    """
    if not t.is_contiguous():
        t = t.contiguous()
    words = t.reshape(-1).view(torch.int32)
    n = t.numel() if numel is None else numel
    if words.numel() > n:
        words = words[:n]
    return words


def _launch_scalar(xb, out, degree):
    total = out.numel()
    if xb.is_contiguous():
        if total <= _SMALL_TOTAL:
            _cheb_t_small_kernel[(triton.cdiv(total, _SMALL_BLOCK),)](
                xb,
                out,
                total,
                DEGREE=degree,
                BLOCK=_SMALL_BLOCK,
                num_warps=_SMALL_WARPS,
            )
        else:
            block, grid_n, warps = _pick(total)
            _cheb_t_scalar_kernel[(grid_n,)](
                xb, out, total, DEGREE=degree, BLOCK=block, num_warps=warps
            )
        return
    dims, xs = _pad_dims(xb)
    _cheb_t_strided_kernel[_grid(total, _BLOCK)](
        xb,
        xb,
        out,
        total,
        *dims,
        *xs,
        *([0] * _MAX_DIMS),
        DEGREE=degree,
        HAS_N=False,
        BLOCK=_BLOCK,
        num_warps=_NUM_WARPS,
    )


def _launch_tensor(xb, nb, nbase, out):
    total = out.numel()
    is_i64 = nb.dtype == torch.int64
    if xb.is_contiguous() and nb.is_contiguous() and nb.numel() == total:
        nptr = _word_view(nb) if is_i64 else nb
        _cheb_t_tensor_kernel[_grid(total, _BLOCK)](
            xb,
            nptr,
            out,
            total,
            BLOCK=_BLOCK,
            num_warps=_NUM_WARPS,
        )
        return
    if is_i64:
        # The word view is only valid for a contiguous source, so densify the
        # broadcast copy and take the strides from that dense copy (one int32
        # word per degree element).
        nb = nb.contiguous()
        nbase = nb
        nptr = _word_view(nbase)
    else:
        nptr = nbase
    dims, xs = _pad_dims(xb)
    _, ns = _pad_dims(nb)
    _cheb_t_strided_kernel[_grid(total, _BLOCK)](
        xb,
        nptr,
        out,
        total,
        *dims,
        *xs,
        *ns,
        DEGREE=0,
        HAS_N=True,
        BLOCK=_BLOCK,
        num_warps=_NUM_WARPS,
    )


def _chebyshev_polynomial_t(x, n, out=None):
    if not isinstance(x, torch.Tensor):
        raise TypeError("special_chebyshev_polynomial_t expects a tensor input")
    if x.dtype not in _FLOAT_DTYPES:
        raise ValueError(
            "special_chebyshev_polynomial_t only supports float32/float64, "
            f"got {x.dtype}"
        )

    if isinstance(n, torch.Tensor):
        if n.numel() == 1:
            # A one element degree cannot extend any dimension, so only a 0-dim
            # x can broadcast to a different shape.
            out_shape = n.shape if x.dim() == 0 else x.shape
            scalar_n = True
        else:
            out_shape = torch.broadcast_shapes(x.shape, n.shape)
            scalar_n = False
    else:
        out_shape = x.shape
        scalar_n = True

    if out is None:
        res = torch.empty(out_shape, dtype=x.dtype, device=x.device)
    else:
        if tuple(out.shape) != out_shape:
            raise ValueError(
                "Incompatible output shape: expected "
                f"{out_shape}, got {tuple(out.shape)}"
            )
        # Strided stores are not supported; stage through a contiguous buffer
        # and copy back for a non-contiguous ``out``.
        res = (
            out
            if out.is_contiguous()
            else torch.empty_like(out, memory_format=torch.contiguous_format)
        )

    total = res.numel()
    if total == 0:
        if res is not out and out is not None:
            out.copy_(res)
        return res

    xb = x if x.shape == out_shape else x.expand(out_shape)

    if isinstance(n, torch.Tensor):
        nptr = _word_view(n) if n.dtype == torch.int64 else n
        if scalar_n and xb.is_contiguous():
            if total <= _SMALL_TOTAL:
                _cheb_t_small_n_kernel[(triton.cdiv(total, _SMALL_BLOCK),)](
                    xb,
                    nptr,
                    res,
                    total,
                    BLOCK=_SMALL_BLOCK,
                    num_warps=_SMALL_WARPS,
                )
            else:
                block, grid_n, warps = _pick(total)
                _cheb_t_scalar_n_kernel[(grid_n,)](
                    xb,
                    nptr,
                    res,
                    total,
                    BLOCK=block,
                    num_warps=warps,
                )
        else:
            nb = n if n.shape == out_shape else n.expand(out_shape)
            _launch_tensor(xb, nb, n, res)
    else:
        _launch_scalar(xb, res, int(n))

    if res is not out and out is not None:
        out.copy_(res)
    return out if out is not None else res


def special_chebyshev_polynomial_t(x, n):
    logger.debug("GEMS SPECIAL_CHEBYSHEV_POLYNOMIAL_T")
    return _chebyshev_polynomial_t(x, n)


def special_chebyshev_polynomial_t_out(x, n, out):
    """Out-of-place variant for special_chebyshev_polynomial_t.

    ATen wrapper: special_chebyshev_polynomial_t.out(Tensor x, Scalar n, *, Tensor(a!) out) -> Tensor(a!)
    """
    logger.debug("GEMS SPECIAL_CHEBYSHEV_POLYNOMIAL_T_OUT")
    return _chebyshev_polynomial_t(x, n, out=out)
